#include <iostream>
#include <string>
using namespace std;

int main() {
    string typed;

    cout << "How many tickets? ";
    getline(cin, typed);          // text, even if it is digits
    int tickets = stoi(typed);    // now a real number

    cout << "That will be " << tickets * 250 << " rupees." << endl;
    return 0;
}

